  meta {
    version: "1.0.0"
    description: "attack base"
  }

  agent alpha {
    description: "Alpha"
    model: sonnet
    hooks {
      hook a1 {
        on: PreToolUse
        matcher: "Bash"
        run: "scripts/a1.sh"
      }
      }
    hooks {
      hook a2 {
        on: PostToolUse
        matcher: "Bash"
        run: "scripts/a2.sh"
      }
      }
    prompt {
      x
    }
  }

  agent beta {
    model: haiku
    prompt {
      Do beta.
    }
  }

  flow {
    alpha -> beta
  }
}
